export function buildInitialState(): SliderStoreState {
  const definitions: Record<SliderId, SliderDefinition> = {};
  const sliders: Record<SliderId, SliderRuntimeState> = {};
  const columns: SliderColumn[] = [];
  const selectionGrids: Record<SelectionGridId, SelectionGridState> = {};
  const selectionGridIds: SelectionGridId[] = [];
  const audioBins = Array.from({ length: AUDIO_BIN_CAPACITY }, () => 0);

  const columnCount = sliderGroups[0]?.variants.length ?? 0;

  for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
    const columnSliderIds: SliderId[] = [];
    sliderGroups.forEach((group) => {
      const variant = group.variants[columnIndex];
      if (!variant) return;
      const id = `${group.hue}-${variant.key}`;
      const colorA = variant.colorA ?? flexoki[group.hue]["600"];
      const colorB = variant.colorB ?? flexoki[group.hue]["100"];
      definitions[id] = {
        id,
        label: variant.label,
        hue: group.hue,
        min: group.min,
        max: group.max,
        step: group.step,
        width: group.width,
        drawerHandle: true,
      };
      sliders[id] = {
        value: randomValue({ min: group.min, max: group.max, step: group.step }),
        colorA,
        colorB,
        border: "none",
        drawerFeatureEnabled: definitions[id].drawerHandle,
        drawerLines: [
          valueFromSplit(Math.random(), group.min, group.max, group.step),
          valueFromSplit(Math.random(), group.min, group.max, group.step),
        ],
        drawerOpen: false,
        lfoEnabled: true,
        waveform: waveformOptions[Math.floor(Math.random() * waveformOptions.length)],
        frequency: randomFrequency(),
        phase: randomPhase(),
        audioResponse: 0,
        audioSamplePosition: 0.5,
      };
      columnSliderIds.push(id);
    });
    columns.push({ id: `column-${columnIndex}`, sliderIds: columnSliderIds });
  }

  const customSliderId = "custom-primary";
  const customMin = 0;
  const customMax = 100;
  const customStep = 1;

  definitions[customSliderId] = {
    id: customSliderId,
    label: "Custom colors",
    hue: "base",
    min: customMin,
    max: customMax,
    step: customStep,
    width: 320,
    drawerHandle: true,
  };
  sliders[customSliderId] = {
    value: randomValue({ min: customMin, max: customMax, step: customStep }),
    colorA: "#205EA6",
    colorB: "#ECCB60",
    border: "none",
    drawerFeatureEnabled: definitions[customSliderId].drawerHandle,
    drawerLines: [
      valueFromSplit(Math.random(), customMin, customMax, customStep),
      valueFromSplit(Math.random(), customMin, customMax, customStep),
    ],
    drawerOpen: true,
    lfoEnabled: true,
    waveform: waveformOptions[Math.floor(Math.random() * waveformOptions.length)],
    frequency: randomFrequency(),
    phase: randomPhase(),
    audioResponse: 0,
    audioSamplePosition: 0.5,
  };

  selectionGrids[DEFAULT_SELECTION_GRID_ID] = normalizeSelectionGridState({
    ...SELECTION_GRID_BASE_STATE,
  });
  selectionGridIds.push(DEFAULT_SELECTION_GRID_ID);

  return {
    definitions,
    sliders,
    columns,
    customSliderId,
    selectionGrids,
    selectionGridIds,
    audioBins,
    audioBinCount: DEFAULT_AUDIO_BIN_COUNT,
    audioMaxMagnitude: DEFAULT_AUDIO_MAX_MAGNITUDE,
  };
}

export function sliderStoreReducer(state: SliderStoreState, action: SliderStoreAction): SliderStoreState {
  switch (action.type) {
    case "setValue":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            value: clamp(action.value, state.definitions[action.id].min, state.definitions[action.id].max),
          },
        },
      };
    case "setColors":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            colorA: action.colorA,
            colorB: action.colorB,
          },
        },
      };
    case "setBorder":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            border: action.border,
          },
        },
      };
    case "setDrawerLines":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            drawerLines: action.lines,
          },
        },
      };
    case "setDrawerFeatureEnabled": {
      const current = state.sliders[action.id];
      if (!current) return state;
      const nextSlider: SliderRuntimeState = action.enabled
        ? { ...current, drawerFeatureEnabled: true }
        : { ...current, drawerFeatureEnabled: false, drawerOpen: false, lfoEnabled: false };
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: nextSlider,
        },
      };
    }
    case "setDrawerOpen": {
      const current = state.sliders[action.id];
      if (!current) return state;
      const drawerOpen = current.drawerFeatureEnabled ? action.open : false;
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...current,
            drawerOpen,
          },
        },
      };
    }
    case "setLfoEnabled":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            lfoEnabled: action.enabled,
          },
        },
      };
    case "setWaveform":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            waveform: action.waveform,
          },
        },
      };
    case "setFrequency":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            frequency: action.frequency,
          },
        },
      };
    case "setPhase":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            phase: action.phase,
          },
        },
      };
    case "setAudioResponse":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            audioResponse: clamp(action.audioResponse, AUDIO_RESPONSE_MIN, AUDIO_RESPONSE_MAX),
          },
        },
      };
    case "setAudioSamplePosition":
      return {
        ...state,
        sliders: {
          ...state.sliders,
          [action.id]: {
            ...state.sliders[action.id],
            audioSamplePosition: clamp(action.audioSamplePosition, 0, 1),
          },
        },
      };
    case "setDrawerOpenBatch": {
      const nextSliders = { ...state.sliders };
      action.ids.forEach((id) => {
        const current = nextSliders[id];
        if (!current) return;
        const drawerOpen = current.drawerFeatureEnabled ? action.open : false;
        nextSliders[id] = { ...current, drawerOpen };
      });
      return { ...state, sliders: nextSliders };
    }
    case "setDrawerFeatureEnabledBatch": {
      const nextSliders = { ...state.sliders };
      action.ids.forEach((id) => {
        const current = nextSliders[id];
        if (!current) return;
        nextSliders[id] = action.enabled
          ? { ...current, drawerFeatureEnabled: true }
          : { ...current, drawerFeatureEnabled: false, drawerOpen: false, lfoEnabled: false };
      });
      return { ...state, sliders: nextSliders };
    }
    case "setLfoEnabledBatch": {
      const nextSliders = { ...state.sliders };
      action.ids.forEach((id) => {
        const current = nextSliders[id];
        if (!current) return;
        nextSliders[id] = { ...current, lfoEnabled: action.enabled };
      });
      return { ...state, sliders: nextSliders };
    }
    case "swapColorsAll": {
      const nextSliders = Object.fromEntries(
        Object.entries(state.sliders).map(([id, slider]) => [
          id,
          { ...slider, colorA: slider.colorB, colorB: slider.colorA },
        ]),
      );
      return { ...state, sliders: nextSliders };
    }
    case "swapColorsColumn": {
      const nextSliders = { ...state.sliders };
      action.ids.forEach((id) => {
        const current = nextSliders[id];
        if (!current) return;
        nextSliders[id] = { ...current, colorA: current.colorB, colorB: current.colorA };
      });
      return { ...state, sliders: nextSliders };
    }
    case "setBorderColumn": {
      const nextSliders = { ...state.sliders };
      action.ids.forEach((id) => {
        const current = nextSliders[id];
        if (!current) return;
        nextSliders[id] = { ...current, border: action.border };
      });
      return { ...state, sliders: nextSliders };
    }
    case "registerSelectionGrid": {
      const current = state.selectionGrids[action.id];
      if (current) {
        const next = normalizeSelectionGridState({ ...current, ...(action.initialState ?? {}) });
        if (selectionGridStatesEqual(next, current)) return state;
        return {
          ...state,
          selectionGrids: {
            ...state.selectionGrids,
            [action.id]: next,
          },
        };
      }
      const next = normalizeSelectionGridState({ ...SELECTION_GRID_BASE_STATE, ...(action.initialState ?? {}) });
      return {
        ...state,
        selectionGridIds: state.selectionGridIds.includes(action.id)
          ? state.selectionGridIds
          : [...state.selectionGridIds, action.id],
        selectionGrids: {
          ...state.selectionGrids,
          [action.id]: next,
        },
      };
    }
    case "updateSelectionGrid": {
      const current = state.selectionGrids[action.id];
      if (!current) return state;
      const next = normalizeSelectionGridState({ ...current, ...action.patch });
      if (selectionGridStatesEqual(next, current)) {
        return state;
      }
      return {
        ...state,
        selectionGrids: {
          ...state.selectionGrids,
          [action.id]: next,
        },
      };
    }
    case "toggleSelectionGridInvert": {
      const current = state.selectionGrids[action.id];
      if (!current) return state;
      const next = { ...current, invertGradients: !current.invertGradients };
      return {
        ...state,
        selectionGrids: {
          ...state.selectionGrids,
          [action.id]: next,
        },
      };
    }
    case "setSelectionGridPalette": {
      const current = state.selectionGrids[action.id];
      if (!current) return state;
      if (current.colorPalette.length === action.palette.length
        && current.colorPalette.every((color, index) => color === action.palette[index])) {
        return state;
      }
      return {
        ...state,
        selectionGrids: {
          ...state.selectionGrids,
          [action.id]: {
            ...current,
            colorPalette: [...action.palette],
          },
        },
      };
    }
    case "setSelectionGridPreviewMode": {
      const current = state.selectionGrids[action.id];
      if (!current) return state;
      if (current.previewMode === action.previewMode) {
        return state;
      }
      const next = normalizeSelectionGridState({ ...current, previewMode: action.previewMode });
      if (selectionGridStatesEqual(next, current)) {
        return state;
      }
      return {
        ...state,
        selectionGrids: {
          ...state.selectionGrids,
          [action.id]: next,
        },
      };
    }
    case "setAudioBins": {
      const nextBins = Array.from({ length: AUDIO_BIN_CAPACITY }, (_, index) => action.bins[index] ?? 0);
      return {
        ...state,
        audioBins: nextBins,
      };
    }
    case "setAudioBinCount": {
      const normalized = Math.max(0, Math.min(AUDIO_BIN_CAPACITY, Math.floor(action.count)));
      if (state.audioBinCount === normalized) return state;
      return {
        ...state,
        audioBinCount: normalized,
      };
    }
    case "setAudioMaxMagnitude": {
      const normalized = Number.isFinite(action.magnitude) && action.magnitude > 0
        ? action.magnitude
        : DEFAULT_AUDIO_MAX_MAGNITUDE;
      if (state.audioMaxMagnitude === normalized) return state;
      return {
        ...state,
        audioMaxMagnitude: normalized,
      };
    }
    default:
      return state;
  }
}
